sys_script_include.script:
var DisplayDuplicateSWProdModels = Class.create();
DisplayDuplicateSWProdModels.prototype = {
    initialize: function() {},

    getDupes: function() {
        var duplicates = {};

        var gaDupCheck = new GlideAggregate('cmdb_software_product_model');
        gaDupCheck.addAggregate('COUNT', 'display_name');
        gaDupCheck.addNotNullQuery('display_name');
        gaDupCheck.groupBy('display_name');
        gaDupCheck.addHaving('COUNT', '>', 1);
        gaDupCheck.query();

        while (gaDupCheck.next()) {
            var displayName = gaDupCheck.getValue('display_name');
            var count = gaDupCheck.getAggregate('COUNT', 'display_name');

            var grDupDetails = new GlideRecord('cmdb_software_product_model');
            grDupDetails.addQuery('display_name', displayName);
            grDupDetails.query();

            var sysIds = [];
            while (grDupDetails.next()) {
                sysIds.push(grDupDetails.getValue('sys_id'));
            }

            duplicates[displayName] = {
                count: parseInt(count, 10),
                sys_ids: sysIds
            };
        }

        return duplicates; // Return the JSON object
    },

    // Enable client-callable methods
    type: 'DisplayDuplicateSWProdModels' // Name of the Script Include
};
